import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import './Home.css';

/* ─────────────────────────────────────────────────────────
   HOOKS
───────────────────────────────────────────────────────── */

/** Fires once when the referenced element enters the viewport. */
function useInView(threshold = 0.18) {
  const ref  = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setInView(true); },
      { threshold }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);

  return [ref, inView];
}

/** Counts from 0 → end over `duration` ms, starting only when `go` is true. */
function useCounter(end, duration = 1400, go = false) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!go) return;
    let id;
    let start = null;
    const step = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      // ease-out quad
      setCount(Math.floor((1 - (1 - progress) ** 2) * end));
      if (progress < 1) id = requestAnimationFrame(step);
    };
    id = requestAnimationFrame(step);
    return () => cancelAnimationFrame(id);
  }, [end, duration, go]);
  return count;
}

/* ─────────────────────────────────────────────────────────
   SUB-COMPONENTS
───────────────────────────────────────────────────────── */

/* ── Navbar ── */
function Navbar() {
  const [open, setOpen] = useState(false);

  // close on outside click
  useEffect(() => {
    const close = (e) => {
      if (!e.target.closest('.dn')) setOpen(false);
    };
    document.addEventListener('click', close);
    return () => document.removeEventListener('click', close);
  }, []);

  return (
    <nav className="dn" aria-label="Main navigation">
      <Link to="/" className="dn__logo" aria-label="Duck Robotics Home">
        DUCK
      </Link>

      {/* Hamburger */}
      <button
        className={`dn__burger${open ? ' open' : ''}`}
        onClick={() => setOpen((v) => !v)}
        aria-label="Toggle navigation menu"
        aria-expanded={open}
      >
        <span /><span /><span />
      </button>

      {/* Link list */}
      <div className={`dn__links${open ? ' open' : ''}`} role="menubar">
        {[
          { label: 'Home',      to: '/'        },
          { label: 'Apply',     to: '/apply'   },
          { label: 'Outreach',  to: '/outreach'},
          { label: 'Contact',   to: '/contact' },
        ].map(({ label, to }) => (
          <Link
            key={label}
            to={to}
            className={`dn__link${label === 'Home' ? ' dn__link--active' : ''}`}
            onClick={() => setOpen(false)}
            role="menuitem"
          >
            {label}
          </Link>
        ))}
        <a
          className="dn__link"
          href="/#sponsors"
          onClick={() => setOpen(false)}
          role="menuitem"
        >
          Sponsors
        </a>
      </div>
    </nav>
  );
}

/* ── Animated stat counter ── */
function Stat({ value, suffix = '', label, color }) {
  const [ref, inView] = useInView(0.5);
  const count = useCounter(value, 1400, inView);
  return (
    <div ref={ref}>
      <div className="stat__num" style={{ color }}>
        {count}{suffix}
      </div>
      <div className="stat__lbl">{label}</div>
    </div>
  );
}

/* ── Community card ── */
function CommunityCard({ tag, tagBg, icon, title, desc, img, imgAlt }) {
  return (
    <article className="cc" aria-label={title}>
      <div className="cc__img-wrap">
        <img src={img} alt={imgAlt} className="cc__img" loading="lazy" />
        <div className="cc__overlay" aria-hidden="true" />
        <span className="cc__pill" style={{ background: tagBg }}>
          {tag}
        </span>
      </div>
      <div className="cc__body">
        <span className="cc__icon" role="img" aria-hidden="true">{icon}</span>
        <h3 className="cc__title">{title}</h3>
        <p  className="cc__desc" >{desc}</p>
      </div>
    </article>
  );
}

/* ── Blueprint spec card ── */
function BlueprintCard({ icon, tag, title, specs, accent }) {
  return (
    <div
      className={`bp__card bp__card--${accent}`}
      role="region"
      aria-label={title}
    >
      <div className="bp__card-hd">
        <span className="bp__card-icon" role="img" aria-hidden="true">{icon}</span>
        <span className="bp__card-tag">{tag}</span>
      </div>
      <h3 className="bp__card-title">{title}</h3>
      <ul className="bp__specs">
        {specs.map((s) => (
          <li key={s}>
            <span className="bp__bullet" aria-hidden="true">▸</span>
            {s}
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────
   PAGE CONTENT DATA
───────────────────────────────────────────────────────── */

const COMMUNITY_CARDS = [
  {
    tag:    'Free Youth Tutoring',
    tagBg:  '#8B5CF6',
    icon:   '🎓',
    title:  'BASE Robotics',
    desc:   'We co-founded this nonprofit to deliver free FTC robotics education to underprivileged students — zero cost, real hardware, maximum impact.',
    img:    '/base-logo.png',
    imgAlt: 'BASE Robotics logo',
  },
  {
    tag:    'Live Demo',
    tagBg:  '#FFD900',
    icon:   '🤖',
    title:  'Elementary Open Houses',
    desc:   'We bring our full competition robot to local school open houses — letting kids drive it, ask questions, and leave excited about engineering.',
    img:    '/jfs_event.png',
    imgAlt: 'Duck Robotics presenting at JFS Elementary Open House',
  },
  {
    tag:    'FTC Collaboration',
    tagBg:  '#22C55E',
    icon:   '🤝',
    title:  'Team Network',
    desc:   'We mentor and collaborate with 4+ FTC teams in the Bay Area — sharing CAD files, Java code, and strategic gameplay insights across our region.',
    img:    '/voltage_meeting.png',
    imgAlt: 'Duck Robotics meeting with Voltage Vanguards',
  },
];

const MECH_SPECS = [
  'Custom-machined mecanum drivetrain',
  'Iterative CAD prototyping workflow',
  'Precision 4-stage linear slide system',
  'Weight-optimized aluminum superstructure',
];

const SW_SPECS = [
  'NextFTC state-machine framework (Java)',
  'Roadrunner v1 autonomous path planning',
  'PID-tuned lift & intake subsystems',
  'Live telemetry dashboard via FTC Dashboard',
];

/* ─────────────────────────────────────────────────────────
   HOME PAGE
───────────────────────────────────────────────────────── */

export default function Home() {
  const [heroRef, heroInView] = useInView(0.12);

  return (
    <div className="home">
      <Navbar />

      {/* ── HERO ──────────────────────────────────────── */}
      <section className="hero" id="home" ref={heroRef} aria-label="Hero">

        {/* Left: Brand copy */}
        <div className={`hero__l${heroInView ? ' in' : ''}`}>

          <div className="hero__badge" aria-hidden="true">
            <span className="hero__dot" />
            FTC TEAM 30473 · DUBLIN, CA
          </div>

          <h1 className="hero__hl" aria-label="Team Duck Robotics">
            <span className="hero__hl-sm"  aria-hidden="true">TEAM</span>
            <span className="hero__hl-duck"aria-hidden="true">DUCK</span>
            <span className="hero__hl-sub" aria-hidden="true">ROBOTICS</span>
          </h1>

          <p className="hero__tag">
            Debug. Deploy. <strong>Duck.</strong>
          </p>

          <div className="hero__ctas">
            <a
              href="mailto:duck30473ftc@gmail.com"
              className="btn btn--primary"
              id="cta-sponsor"
              aria-label="Email us to support our journey"
            >
              Support Our Journey
              <span className="btn__arrow" aria-hidden="true">↗</span>
            </a>
            <Link to="/outreach" className="btn btn--outline" id="cta-outreach">
              Our Outreach
              <span className="btn__arrow" aria-hidden="true">→</span>
            </Link>
          </div>

          {/* Animated stats */}
          <div className="hero__stats" aria-label="Team statistics">
            <Stat value={4}   suffix=""    label="Competitions"      color="#FFD900" />
            <div className="hero__divider" aria-hidden="true" />
            <Stat value={20}  suffix="+"   label="Match Wins"        color="#FFFFFF" />
            <div className="hero__divider" aria-hidden="true" />
            <Stat value={100} suffix="+"   label="Students Reached"  color="#FFD900" />
          </div>
        </div>

        {/* Right: Action photo */}
        <div className={`hero__r${heroInView ? ' in' : ''}`} aria-hidden="true">
          <div className="hero__frame">
            <img
              src="/jfs_event.png"
              alt="Duck Robotics drive team presenting at an outreach event"
              className="hero__img"
              fetchpriority="high"
            />
            <div className="hero__badge-img">
              <span className="material-symbols-outlined" aria-hidden="true">
                emoji_events
              </span>
              Connect Award — EBLT 2025
            </div>
          </div>
        </div>

      </section>

      {/* ── COMMUNITY IMPACT ──────────────────────────── */}
      <section className="community" id="community" aria-labelledby="community-title">
        <div className="community__wrap">
          <header className="sh">
            <div className="sh__eye" aria-hidden="true">
              <span className="sh__line" />
              COMMUNITY IMPACT
              <span className="sh__line" />
            </div>
            <h2 className="sh__title" id="community-title">Beyond the Robot</h2>
            <p  className="sh__sub">
              We engineer opportunities, not just machines.
            </p>
          </header>

          <div className="community__grid">
            {COMMUNITY_CARDS.map((c) => (
              <CommunityCard key={c.title} {...c} />
            ))}
          </div>
        </div>
      </section>

      {/* ── ENGINEERING BLUEPRINT TEASER ──────────────── */}
      <section className="bp" id="engineering" aria-labelledby="bp-title">
        <div className="bp__inner">
          <header className="sh">
            <div className="sh__eye" aria-hidden="true">
              <span className="sh__line sh__line--dk" />
              ENGINEERING SYSTEMS
              <span className="sh__line sh__line--dk" />
            </div>
            <h2 className="sh__title sh__title--dk" id="bp-title">Under the Hood</h2>
            <p  className="sh__sub  sh__sub--dk">
              A peek at the systems powering Team Duck on the competition field.
            </p>
          </header>

          <div className="bp__grid">
            <BlueprintCard
              icon="⚙️"
              tag="MECHANICAL"
              title="Custom Chassis Architecture"
              specs={MECH_SPECS}
              accent="mech"
            />
            <BlueprintCard
              icon="💻"
              tag="SOFTWARE"
              title="Java / NextFTC Architecture"
              specs={SW_SPECS}
              accent="soft"
            />
          </div>

          <div className="bp__cta">
            <Link to="/outreach" className="btn btn--primary" id="cta-tech-specs">
              View Our Outreach
              <span className="btn__arrow" aria-hidden="true">→</span>
            </Link>
            <Link to="/apply" className="btn btn--ghost" id="cta-join-build">
              Join the Build Team
              <span className="btn__arrow" aria-hidden="true">→</span>
            </Link>
          </div>
        </div>
      </section>

      {/* ── FOOTER ────────────────────────────────────── */}
      <footer className="duck-footer" role="contentinfo">
        <div className="duck-footer__inner">
          <div className="duck-footer__brand">
            <span className="duck-footer__logo">DUCK</span>
            <span className="duck-footer__team">FTC Team 30473 · Dublin, CA</span>
          </div>
          <nav className="duck-footer__links" aria-label="Footer navigation">
            <Link to="/apply">Apply</Link>
            <Link to="/outreach">Outreach</Link>
            <Link to="/contact">Contact</Link>
          </nav>
          <div className="duck-footer__copy">© 2026 FTC Team Duck 30473</div>
        </div>
      </footer>
    </div>
  );
}
